from course_model import *
c=chapter('json','JSON · date și fișiere de configurare','Formate stricte, parsare, reviver, replacer și datele galeriei.','JSON.pptx, 3–20; resurse/json/galerie.json și erori.json','database')
def JJ(id,title,idea,solution,cases,quiz,prompt,slides=''):
 lesson(c,id,title,idea,solution,idea,quiz,js(prompt,solution,cases),slides)
lesson(c,'json-syntax','Un format pentru date','JSON este text. Acceptă obiecte, vectori, șiruri, numere, true, false și null. Cheile obiectelor sunt șiruri cu ghilimele duble; nu sunt permise comentarii sau virgulă finală.',
 '{\n  "name": "Cake",\n  "price": 10,\n  "available": true\n}', 'Numărul 10 nu are ghilimele. true este boolean. Un fișier JSON nu execută funcții.',q('Care cheie este validă în JSON?','"name"','name fără ghilimele',"'name'"),dict(mode='json',prompt='Scrie obiectul cu name Cake, price 10 și available true.',solution='{"name":"Cake","price":10,"available":true}',starter='{\n  \n}',expected={'name':'Cake','price':10,'available':True}),'3–8,19')
JJ('json-parse','De la text la obiect','JSON.parse interpretează textul JSON. Dacă textul este invalid, aruncă SyntaxError; nu presupune că un text cu aspect de obiect este deja un obiect.','function solve(input) { return JSON.parse(input).name; }',[('{"name":"Cake"}','Cake'),('{"name":"Tea"}','Tea')],q('Ce primește JSON.parse?','Text JSON','O funcție Express','Un element img'),'Parsează input și returnează proprietatea name.','9–10')
JJ('json-stringify','De la obiect la text','JSON.stringify produce un șir. Funcții și undefined au reguli speciale de omitere sau înlocuire, iar referințele circulare nu pot fi serializate direct.','function solve(input) { return JSON.stringify(input); }',[({'name':'Cake'},'{"name":"Cake"}'),([1,2],'[1,2]')],q('Ce produce stringify?','Un șir','O conexiune SQL','Un DOM'),'Returnează JSON.stringify(input).','15–18')
JJ('json-nested','Obiecte și vectori imbricați','O galerie poate conține un vector de imagini în interiorul unui obiect. După parsare accesezi proprietățile și indicii obișnuiți.','function solve(input) { const gallery = JSON.parse(input); return gallery.images.map(image => image.file); }',[('{"images":[{"file":"cake.webp"},{"file":"tea.webp"}]}',['cake.webp','tea.webp']),('{"images":[]}',[])],q('Cum citești primul element din images?','images[0]','images(1)','images.first obligatoriu'),'Returnează numele fișierelor din images, după parsarea textului input.','8–10; galerie.json')
JJ('json-reviver','Transformare în timpul parsării','Reviver primește fiecare cheie și valoare și poate întoarce o valoare înlocuitoare. Proprietățile imbricate sunt prelucrate înaintea obiectului care le conține.','function solve(input) { return JSON.parse(input, (key, value) => key === "price" ? value * 2 : value); }',[('{"price":10,"name":"Cake"}',{'price':20,'name':'Cake'}),('{"item":{"price":3}}',{'item':{'price':6}})],q('Ce întorci pentru valorile pe care le păstrezi?','Valoarea primită','undefined','Nu returnezi nimic'),'Dublează fiecare proprietate price la parsare.','9–14')
JJ('json-remove','Eliminare prin reviver','Dacă reviver întoarce undefined, proprietatea este eliminată. Funcția este apelată și pentru rezultatul final cu cheia goală, deci trebuie să păstrezi și acea valoare.','function solve(input) { return JSON.parse(input, (key, value) => key === "secret" ? undefined : value); }',[('{"name":"Cake","secret":"x"}',{'name':'Cake'}),('{"nested":{"secret":1,"n":2}}',{'nested':{'n':2}})],q('Ce face return undefined într-un reviver?','Elimină proprietatea','Pune șirul undefined','Transformă în zero'),'Elimină orice proprietate secret.','11–14')
JJ('json-replacer','Selectează proprietăți la serializare','JSON.stringify poate primi un replacer: o listă de chei sau o funcție. El controlează textul produs fără să modifice obiectul original.','function solve(input) { return JSON.stringify(input, ["name", "price"]); }',[({'name':'Cake','price':10,'secret':'x'},'{"name":"Cake","price":10}'),({'name':'Tea'},'{"name":"Tea"}')],q('Replacer modifică automat obiectul original?','Nu; controlează serializarea','Da, șterge proprietățile','Da, dacă există name'),'Serializează doar name și price, în această ordine.','15–18')
JJ('json-format','Indentare pentru fișiere lizibile','Al treilea argument al stringify controlează indentarea. Un fișier bine formatat se citește mai ușor, dar spațiile nu schimbă semnificația datelor.','function solve(input) { return JSON.stringify(input, null, 2); }',[({'name':'Cake'},'{\n  "name": "Cake"\n}')],q('Ce controlează al treilea argument stringify?','Indentarea','Portul serverului','Numele fișierului'),'Returnează JSON cu indentare de două spații.','15–18')
JJ('json-errors','Fallback și configurație validă','Un fișier poate lipsi sau poate conține JSON invalid. Separă erorile de citire de erorile de parsare. Nu continua cu o configurație incompletă fără o regulă explicită.','function solve(input) { try { return JSON.parse(input); } catch { return { error: "Invalid JSON" }; } }',[('{"ok":true}',{'ok':True}),('{bad}',{'error':'Invalid JSON'})],q('Ce poate arunca JSON.parse pentru un text invalid?','SyntaxError','Un cod HTTP automat','O eroare CSS'),'Returnează obiectul parsată sau {error:"Invalid JSON"}.','19; initErori din index.js')

s=chapter('scss','SCSS · compilare reală','Variabile, tipuri, condiții, bucle, module, liste și funcții.','SASS.pptx, 3–29; resurse/scss/nav1.scss și customizare_bootstrap.scss','layers')
def S(id,title,idea,source,fixture,tests,quiz,files=None,explain=None):
 task=css('Scrie SCSS-ul din exemplu. Serverul îl compilează cu Sass, apoi verifică efectul CSS în browser.',source,fixture,tests,mode='scss')
 if files:task['files']=files
 lesson(s,id,title,idea,source,explain or idea,quiz,task)
S('scss-compile','Browserul primește CSS','Sass este un preprocesor. Fișierul SCSS este compilat în CSS, iar pagina încarcă rezultatul CSS. Nu pune o adresă .scss ca stylesheet al browserului.','$accent: navy;\n.card { color: $accent; }','<p class="card">Cake</p>',[prop('.card','color','rgb(0, 0, 128)')],q('Ce încarcă browserul ca stylesheet?','CSS-ul compilat','Fișierul SCSS fără compilare','package.json'))
S('scss-variables','Variabile și domeniu','Variabilele Sass încep cu $. Sunt evaluate la compilare. Nu sunt aceleași cu proprietățile CSS --accent, care există în pagina randată.','$space: 12px;\n.card { padding: $space; }','<div class="card">Cake</div>',[prop('.card','padding-top','12px')],q('Când este evaluat $space?','La compilarea Sass','La fiecare clic obligatoriu','În PostgreSQL'))
S('scss-types','Tipuri, liste și unități','Sass lucrează cu numere cu unități, șiruri, culori, booleene, null, liste și hărți. Operațiile trebuie să aibă unități compatibile.','$base: 8px;\n.card { padding: $base * 2; }','<div class="card">Cake</div>',[prop('.card','padding-top','16px')],q('Ce rezultat are 8px * 2?','16px','16rem','O clasă numită 16'))
S('scss-if','Condiții la compilare','@if și @else aleg codul CSS generat. Nu reacționează direct la un clic în browser; alegerea se face când compilezi.','$dark: true;\n.card { @if $dark { color: white; background: navy; } @else { color: black; } }','<div class="card">Cake</div>',[prop('.card','color','rgb(255, 255, 255)'),prop('.card','background-color','rgb(0, 0, 128)')],q('Când se execută @if din SCSS?','La compilare','La fiecare hover','În parserul JSON'))
S('scss-logic','Operatori logici și comparații','Sass folosește and, or și not pentru logică. == și != compară valori. Nu copia automat operatorii && și || din JavaScript.','$enabled: true;\n$compact: false;\n.card { @if $enabled and not $compact { padding: 20px; } }','<div class="card">Cake</div>',[prop('.card','padding-top','20px')],q('Ce operator Sass combină două condiții adevărate?','and','&& obligatoriu','AND() ca funcție SQL'))
S('scss-for','@for și interpolare','@for from ... through include limita finală; to o exclude. Interpolarea #{$index} introduce valoarea în numele selectorului.','@for $index from 1 through 3 {\n  .space-#{$index} { padding: $index * 4px; }\n}','<div class="space-1">1</div><div class="space-2">2</div><div class="space-3">3</div>',[prop('.space-1','padding-top','4px'),prop('.space-2','padding-top','8px'),prop('.space-3','padding-top','12px')],q('through include limita de sus?','Da','Nu','Numai pentru culori'))
S('scss-while','@while și actualizarea condiției','@while repetă generarea cât timp condiția este adevărată. Actualizează variabila pentru a evita o compilare care nu se termină.','$index: 1;\n@while $index <= 2 {\n  .space-#{$index} { margin: $index * 5px; }\n  $index: $index + 1;\n}','<div class="space-1">1</div><div class="space-2">2</div>',[prop('.space-1','margin-top','5px'),prop('.space-2','margin-top','10px')],q('Ce lipsește dintr-o buclă care nu își schimbă niciodată condiția?','O actualizare care permite terminarea','Un fișier HTML obligatoriu','Un selector #root'))
S('scss-use','Module și !default','@use încarcă un modul și oferă namespace. Variabilele marcate !default pot fi configurate prin with când modulul este încărcat prima dată.','@use "palette" with ($accent: navy);\n.card { color: palette.$accent; }','<p class="card">Cake</p>',[prop('.card','color','rgb(0, 0, 128)')],q('Ce permite configurarea unei variabile din modul?','!default','!important','readonly'),{'_palette.scss':'$accent: teal !default;'})
S('scss-list','Liste indexate de la 1','Modulul sass:list oferă nth, length, index, append și set-nth. În Sass primul indice este 1, nu 0.','@use "sass:list";\n$spaces: 4px, 8px, 12px;\n.card { padding: list.nth($spaces, 2); }','<div class="card">Cake</div>',[prop('.card','padding-top','8px')],q('Care este primul indice al unei liste Sass?','1','0','-1'))
S('scss-nesting','Imbricare și selectori','Regulile imbricate combină selectorii. .card { p {...} } produce un descendent .card p. Nu exagera adâncimea selectorilor pentru a evita specificitate greu de controlat.','.card { p { color: navy; } }','<div class="card"><p>Cake</p></div><p>Outside</p>',[prop('.card p','color','rgb(0, 0, 128)'),prop('body > p','color','rgb(0, 0, 0)')],q('Ce selector produce .card { p {...} }?','.card p','.cardp','p.card obligatoriu'))
S('scss-parent','& reprezintă selectorul părinte','& este înlocuit cu selectorul părinte compilat. Fără el, un spațiu poate schimba sensul: a :hover nu este același lucru cu a:hover.','.card { &.active { color: navy; } }','<p class="card active">Cake</p><p class="card">Tea</p>',[prop('.card.active','color','rgb(0, 0, 128)'),prop('.card:not(.active)','color','rgb(0, 0, 0)')],q('Ce produce &.active în .card?','.card.active','.card .active','active.card.card'))
S('scss-combinations','Liste de selectori și combinări','La imbricarea listelor separate prin virgulă, Sass poate genera toate combinațiile. Verifică rezultatul ca să nu creezi selectori mult mai numeroși decât intenționezi.','.card, .panel { p, strong { color: navy; } }','<div class="card"><p>Cake</p></div><div class="panel"><strong>Tea</strong></div>',[prop('.card p','color','rgb(0, 0, 128)'),prop('.panel strong','color','rgb(0, 0, 128)')],q('Cum se combină două liste imbricate de selectori?','Prin toate combinațiile relevante','Doar primul cu primul','Se ignoră lista copil'))
S('scss-root','Ieși din imbricare cu @at-root','@at-root mută regula generată în afara imbricării. Poți salva selectorul părinte într-o variabilă când ai nevoie să îl refolosești mai adânc.','.wrapper { @at-root .notice { color: navy; } }','<p class="notice">Cake</p>',[prop('.notice','color','rgb(0, 0, 128)')],q('Ce face @at-root?','Scoate regula din imbricare','Creează automat :root în HTML','Șterge CSS-ul'))
S('scss-extend','Placeholder și @extend','Un selector placeholder începe cu %. Nu generează o regulă utilizabilă singur; @extend îl leagă de selectorii care îl extind.','%card-base { padding: 12px; }\n.product-card { @extend %card-base; }','<div class="product-card">Cake</div>',[prop('.product-card','padding-top','12px')],q('Ce prefix are un placeholder Sass?','%','$','#'))
S('scss-function','Calculează o valoare cu @function','O funcție Sass primește parametri cu $ și produce o valoare cu @return. Nu este o funcție JavaScript și nu rulează la clic.','@function double-space($value) { @return $value * 2; }\n.card { margin: double-space(6px); }','<div class="card">Cake</div>',[prop('.card','margin-top','12px')],q('Ce instrucțiune returnează valoarea în Sass?','@return','return fără @ obligatoriu','res.send'))
S('scss-bootstrap','Personalizează înainte de compilare','Exemplul profesoarei definește variabile și importă Bootstrap SCSS. Ordinea contează: valorile configurabile sunt date înainte de compilarea componentelor. Proiectul final include Bootstrap local și sursa de personalizare.','$primary: navy;\n.btn-primary { background: $primary; color: white; }','<button class="btn-primary">Products</button>',[prop('.btn-primary','background-color','rgb(0, 0, 128)')],q('Când trebuie aplicată configurarea Sass pentru a afecta CSS-ul?','Înaintea generării CSS-ului componentelor','După închiderea browserului','Doar în localStorage'))
